/** Le halo de points crème, à la manière tingatinga : collé au contour, le long du dos seulement (sur le cou, la crinière prend la suite). */
const HALO =
  "M195.1 495.3a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M207.8 486.6a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M221.1 478.3a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M235.9 471.2a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M250.6 465.8a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M265.2 461.2a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M279.5 456.7a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M294.1 452.4a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M308.5 448.3a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M322.8 444.2a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M337.2 439.9a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M351.5 435.6a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M365.7 431.2a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M379.8 426.6a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M393.8 421.8a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M407.6 416.7a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M421 411.3a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M434 405.1a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0M447.1 398.2a2.7 2.7 0 1 0 5.4 0a2.7 2.7 0 1 0 -5.4 0";
// </tracés>

const CREME = "244,236,214";
const SIENNE = "#8f5131";
const SIENNE_OMBRE = "#6a371d";
const NOIR = "#0a0e0b";
const ROBE_CLAIRE = "#ecdfbf";
/** Le museau : un crème plus chaud, sans taches. */
const MUSEAU_TON = "#d7c2a2";
const ROBE_LOIN = "#cdb98f";

/** Le dos : la girafe peinte, cernée de noir, ses taches, son halo de points. */
function Girafe({ id }: { id: string }) {
  const creme = (a: number) => `rgba(${CREME},${a})`;
  return (
    <g strokeLinejoin="round">
      <defs>
        <clipPath id={`tc-${id}`}>
          <path d={CORPS} />
        </clipPath>
        <clipPath id={`tl-${id}`}>
          <path d={LOIN} />
        </clipPath>
        {/* Le museau : sa limite fondue dans la face (le crème chaud monte du bout du nez), jamais un manchon. */}
        <linearGradient id={`tmu-${id}`} gradientUnits="userSpaceOnUse" x1={736.5} y1={180} x2={754.9} y2={171.8}>
          <stop offset={0} stopColor={MUSEAU_TON} stopOpacity={0} />
          <stop offset={1} stopColor={MUSEAU_TON} />
        </linearGradient>
      </defs>
      <path d={HALO} fill={creme(0.85)} />
      {/* Les pattes lointaines, un ton plus bas */}
      <path d={LOIN} fill={ROBE_LOIN} />
      <g clipPath={`url(#tl-${id})`}>
        <path d={ROBE} fill="#7a4428" stroke={NOIR} strokeWidth={1.4} />
        {/* Les sabots, sombres */}
        <path d="M0 957H1000V1000H0Z" fill={NOIR} />
      </g>
      <path d={LOIN} fill="none" stroke={NOIR} strokeWidth={5} />
      <path d={QUEUE} fill={ROBE_CLAIRE} stroke={NOIR} strokeWidth={3} />
      <path d={TOUFFE} fill={NOIR} />
      {/* Le corps : le réseau crème, les taches de Sienne cernées de noir, leur cœur */}
      <path d={CORPS} fill={ROBE_CLAIRE} />
      <g clipPath={`url(#tc-${id})`}>
        <path d={ROBE} fill={SIENNE} stroke={NOIR} strokeWidth={1.6} />
        <path d={COEURS} fill={SIENNE_OMBRE} />
        {/* La face : le museau plus chaud, les petites taches */}
        <path d={MUSEAU} fill={`url(#tmu-${id})`} />
        <path d={TACHES_TETE} fill={SIENNE} stroke={NOIR} strokeWidth={1.4} />
        {/* Les sabots, sombres */}
        <path d="M0 963H1000V1000H0Z" fill={NOIR} />
      </g>
      <path d={CORPS} fill="none" stroke={NOIR} strokeWidth={6} />
      <path d={OREILLE_IN} fill={SIENNE_OMBRE} />
      <path d={JOUE} fill="none" stroke={NOIR} strokeWidth={2.2} strokeLinecap="round" />
      {/* La crinière courte, par-dessus le bord du cou, ses poils */}
      <path d={CRINIERE} fill={SIENNE_OMBRE} stroke={NOIR} strokeWidth={2.4} />
      <path d={POILS} fill="none" stroke={NOIR} strokeWidth={1.6} strokeLinecap="round" />
      {/* La tête : les touffes des ossicônes, l'œil, son reflet et sa frange de cils, la bouche, la narine */}
      <path d={TOUFFES + OEIL + CILS} fill={NOIR} />
      <path d={REFLET} fill={ROBE_CLAIRE} />
      <path d={TRAITS} fill="none" stroke={NOIR} strokeWidth={2.4} strokeLinecap="round" />
    </g>
  );
}

/**
 * La face : la tête et le cou au pointillé crème (des points ronds, comme les
 * contours tingatinga), les taches à peine teintées, qui montent du bas du
 * portrait à droite de l'équerre et s'effacent vers le bas. Dans la boîte,
 * la tête est grandie (TETE) ; la pose la ramène au coin.
 */
const TETE = "translate(-703.6 -176.7) scale(1.667)";
function Pointille({ id, photo }: { id: string; photo: boolean }) {
  const creme = (a: number) => `rgba(${CREME},${a * (photo ? 1 : 0.88)})`;
  const ombre = `rgba(4,10,6,${photo ? 0.45 : 0.3})`;
  // le pointillé, plus gros sans photo : sur le vert du kanga, il doit se lire autant que sur une photo
  const points = { strokeDasharray: photo ? "0 5.6" : "0 6.4", strokeLinecap: "round" as const };
  const grain = photo ? 2.8 : 3.8;
  return (
    <g transform={TETE} mask={`url(#tm-${id})`}>
      <defs>
        <clipPath id={`tp-${id}`}>
          <path d={CORPS} />
        </clipPath>
        <linearGradient id={`tf-${id}`} x1="0" y1={300} x2="0" y2={470} gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#fff" />
          <stop offset="1" stopColor="#fff" stopOpacity={0} />
        </linearGradient>
        <mask id={`tm-${id}`} maskUnits="userSpaceOnUse" x={420} y={80} width={420} height={420}>
          <rect x={420} y={80} width={420} height={420} fill={`url(#tf-${id})`} />
        </mask>
      </defs>
      <path d={ROBE + TACHES_TETE} fill={`rgba(143,81,49,${photo ? 0.42 : 0.3})`} clipPath={`url(#tp-${id})`} />
      <path d={CORPS} fill="none" stroke={ombre} strokeWidth={grain + 0.6} transform="translate(0.6 0.8)" {...points} />
      <path d={CORPS} fill="none" stroke={creme(photo ? 0.9 : 1)} strokeWidth={grain} {...points} />
      <path d={TOUFFES + OEIL + CILS} fill={creme(0.85)} />
    </g>
  );
}

function Dessin({ couche, photo, id }: PropsTotem) {
  if (couche === "dos") return <Girafe id={id} />;
  if (couche === "face-portrait") return <Pointille id={id} photo={photo} />;
  return null;
}

